//! Chunk 51, x2#1: a pool's rows are every UTxO whose payment credential is
//! its `mix_box` hash M, as Koios's `credential_utxos` lists them. It takes
//! bare 28-byte hashes, a key's or a script's alike (the wallet asks it for
//! both), so a UTxO at an enterprise KEY address whose key hash is M comes
//! back beside the boxes, with `payment_cred` = M. Anyone can pay one: no key
//! hashes to M, so its ADA is burnt. The contract never takes it as a box
//! (`input_at_script` wants `Script(M)`), and the ledger asks no script and no
//! redeemer of a key-locked input. So the wallet must never read it as a box:
//! never count it among the others a fan-out needs, and never draw it into a
//! mix, which the wallet's own measure then refuses (uplc's phase one: a
//! redeemer the transaction doesn't need).

use blstrs::{G1Projective, Scalar};
use ff::Field;
use group::Group;
use pallas_addresses::{
    Address, Network, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_crypto::hash::Hash;
use pallas_primitives::Fragment;
use pallas_txbuilder::Output;
use rand_core::OsRng;
use seedelf_core::eval::{self, Resolved};
use seedelf_core::lovejoin::{self, Coin, Payer, PoolBox, PoolShort, Protocol, Rewards, Version};
use seedelf_crypto::lovejoin as crypto;
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};
use serde_json::{Value as Json, json};

fn params() -> ProtocolParameters {
    let rows: Json = serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    ProtocolParameters::from_koios(&rows[0]).unwrap()
}

/// v2's pool of 5 ₳ boxes of ADA on preprod, verified as the wallet verifies
/// one (`lovejoin_pools_test.rs`'s `v2_ada`): where a return's ADA goes.
fn v2_ada() -> Protocol {
    let doc: Json = serde_json::from_str(include_str!(
        "../../seedelf-web-wallet/wasm/tests/fixtures/lovejoin-v2-ada-pool-preprod.json"
    ))
    .unwrap();
    let row = |v: &Json| serde_json::from_value::<UtxoResponse>(v.clone()).unwrap();
    let reference = eval::resolve_row(&row(&doc["reference"])).unwrap();
    let scripts: Vec<Resolved> = doc["scripts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| {
            let bytes = hex::decode(s["reference_script"]["bytes"].as_str().unwrap()).unwrap();
            eval::resolve_reference(&row(s), 3, &bytes).unwrap()
        })
        .collect();
    let seed: [u8; 32] = hex::decode(doc["seed"]["txHash"].as_str().unwrap())
        .unwrap()
        .try_into()
        .unwrap();
    let pool = lovejoin::verify_pool(
        true,
        &reference,
        (seed, doc["seed"]["txIndex"].as_u64().unwrap()),
        &scripts,
    )
    .unwrap();
    assert_eq!(pool.version, Version::V2);
    assert_eq!(pool.denom, 5_000_000);
    pool
}

fn random_scalar() -> Scalar {
    loop {
        let s = Scalar::random(&mut OsRng);
        if !bool::from(s.is_zero()) {
            return s;
        }
    }
}

/// A box's `{a, b}`: valid G1 points, neither the identity, `a ≠ b`; owned by
/// `sk` (`b = sk·a`) when given.
fn points(sk: Option<&Scalar>) -> ([u8; 48], [u8; 48]) {
    let a = G1Projective::generator() * random_scalar();
    let b = a * sk.copied().unwrap_or_else(random_scalar);
    (crypto::point_to_bytes(&a), crypto::point_to_bytes(&b))
}

/// The enterprise KEY address whose key hash is `pool`'s `mix_box` script
/// hash: header 0x60 on preprod, 0x61 on mainnet.
fn twin(pool: &Protocol) -> Address {
    let network = if pool.network_flag {
        Network::Testnet
    } else {
        Network::Mainnet
    };
    ShelleyAddress::new(
        network,
        ShelleyPaymentPart::Key(Hash::new(pool.mix_box_hash)),
        ShelleyDelegationPart::Null,
    )
    .into()
}

/// A row as Koios's `credential_utxos` for M lists it: exactly the box value
/// at `address`, a box's inline datum, and `payment_cred` M (the key hash of
/// the twin is M, as the script hash of `mix_box` is).
fn row(pool: &Protocol, address: &Address, first: u8, (a, b): ([u8; 48], [u8; 48])) -> UtxoResponse {
    serde_json::from_value(json!({
        "tx_hash": hex::encode([first; 32]), "tx_index": 0,
        "address": address.to_bech32().unwrap(),
        "value": pool.denom.to_string(), "stake_address": null,
        "payment_cred": hex::encode(pool.mix_box_hash), "epoch_no": 0,
        "block_height": 0, "block_time": 0, "datum_hash": null,
        "inline_datum": { "bytes": hex::encode(lovejoin::mix_datum(&a, &b)), "value": null },
        "reference_script": null, "asset_list": [], "is_spent": false,
    }))
    .unwrap()
}

/// A session's base address on preprod, and ADA alone at it.
fn session() -> Address {
    let mut raw = vec![0x00];
    raw.extend([0x51; 28]);
    raw.extend([0x52; 28]);
    Address::from_bytes(&raw).unwrap()
}

fn coin(first: u8, lovelace: u64) -> Coin {
    Coin {
        utxo: Resolved {
            tx_hash: [first; 32],
            index: 0,
            output: Output::new(session(), lovelace)
                .build_babbage_raw()
                .unwrap()
                .encode_fragment()
                .unwrap(),
        },
        lovelace,
    }
}

fn payer() -> Payer {
    Payer {
        fee: coin(0xf1, 50_000_000),
        collateral: Some(coin(0xcc, 5_000_000)),
        address: session(),
        signers: 1,
    }
}

#[test]
fn a_key_address_under_a_pools_mix_box_hash_is_never_read_as_a_box() {
    let params = params();
    let mut wrong: Vec<String> = Vec::new();

    // 1. The row itself: in v2's 5 ₳ pool, and the classic pools of both networks.
    for pool in [
        v2_ada(),
        Protocol::of(true).unwrap(),
        Protocol::of(false).unwrap(),
    ] {
        let header = |a: &Address| a.to_vec()[0] >> 4;
        assert_eq!(header(&pool.mix_box_address()), 0x7, "mix_box: enterprise script");
        assert_eq!(header(&twin(&pool)), 0x6, "the twin: enterprise key");
        let real = row(&pool, &pool.mix_box_address(), 0x31, points(None));
        assert!(
            PoolBox::from_row(&real, &pool).is_some(),
            "a real box is read as one"
        );
        let fake = row(&pool, &twin(&pool), 0x32, points(None));
        if let Some(b) = PoolBox::from_row(&fake, &pool) {
            wrong.push(format!(
                "[row] {} ₳ at {} (a KEY address whose hash is mix_box's {}) is read as a box \
                 of the pool's: PoolBox {{ a: {}…, utxo output's address header {:#04x} }}",
                pool.denom / 1_000_000,
                twin(&pool).to_bech32().unwrap(),
                hex::encode(pool.mix_box_hash),
                &hex::encode(b.a)[..16],
                b.utxo.output.get(4).copied().unwrap_or_default(),
            ));
        }
    }

    // 2. A mix of the boxes the wallet reads from v2's 5 ₳ pool's rows: three
    // real ones and the twin. Every box it reads must be one a mix can take.
    let pool = v2_ada();
    let mut rows: Vec<UtxoResponse> = (0..3u8)
        .map(|i| row(&pool, &pool.mix_box_address(), 0x40 + i, points(None)))
        .collect();
    rows.push(row(&pool, &twin(&pool), 0x4f, points(None)));
    let boxes: Vec<PoolBox> = rows
        .iter()
        .filter_map(|r| PoolBox::from_row(r, &pool))
        .collect();
    if let Err(e) = lovejoin::mix(&params, &pool, &boxes, &payer(), &mut Rewards::none()) {
        wrong.push(format!(
            "[mix] the wallet read {} boxes from 3 real rows and the twin, and a mix of them \
             fails in the wallet's own measure: {e:#}",
            boxes.len()
        ));
    }

    // 3. Mixing again one box of the wallet's, one wave three wide, where the
    // pool's others are one real box and the twin: it needs two others, and
    // the pool has one, so it's short (PoolShort), never a chain that draws
    // the twin and fails to build.
    let sk = random_scalar();
    let rows = [
        row(&pool, &pool.mix_box_address(), 0x50, points(Some(&sk))),
        row(&pool, &pool.mix_box_address(), 0x51, points(None)),
        row(&pool, &twin(&pool), 0x52, points(None)),
    ];
    let (ours, others): (Vec<PoolBox>, Vec<PoolBox>) = rows
        .iter()
        .filter_map(|r| PoolBox::from_row(r, &pool))
        .partition(|b| b.is_owned(&sk));
    assert_eq!(ours.len(), 1, "the wallet's own box is read as its");
    match lovejoin::again_at(&params, &pool, &payer(), &ours, 1, 3, &others, &mut Rewards::none()) {
        Err(e) if e.downcast_ref::<PoolShort>() == Some(&PoolShort { have: 1, needed: 2 }) => {}
        Err(e) => wrong.push(format!(
            "[fan-out] the pool's others counted {} (1 real, the twin), so the fan-out drew \
             the twin instead of saying the pool is short, and the chain failed: {e:#}",
            others.len()
        )),
        Ok(_) => wrong.push(format!(
            "[fan-out] a chain built from {} others where only 1 is a box",
            others.len()
        )),
    }

    assert!(wrong.is_empty(), "\n{}", wrong.join("\n\n"));
}

// Chunk 51, finding x1a#1 (lane X1a), its trace verifier's test. Anyone can pair the public account's receive key
// 0/0, public in every address it hands out, with their own stake key: base(0/0, a stranger's stake key). The
// wallet rightly counts and spends that money as the account's (by payment key, privacy review §2.17), so a payment
// there comes back to the balance. But its stake part is the stranger's: while the money sits there, its stake
// earns, and votes, for the stranger's key. The sign window says so of the same shape in a site's transaction
// ("dappUi.warn.ownKey": "... a stake part that isn't yours ... its staking rewards aren't yours"). Send's and Make
// public's reviews must tell it apart from the Receive address too: today the worker answers exactly as it does for
// the Receive address, and each review reads word for word as it does for the Receive address.
//
// The worker's answer is the real one (resolveDestination, through WithdrawService.resolve, as both forms ask it
// and as SendService.build and WithdrawService.build put it in their summaries). The reviews are the real screens,
// rendered over the house's useState seed (screens-wiring-review-fixes.test.ts's seam, trimmed to `seed`): a
// review's state is one only an awaited answer reaches.
import { createElement, type ReactElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

const seam = vi.hoisted(() => {
  /** Whether a useState's initial value is `want`: an empty object for `{}`, or the same value. */
  const matches = (initial: unknown, want: unknown) =>
    want && typeof want === "object" && !Object.keys(want).length
      ? !!initial && typeof initial === "object" && !Array.isArray(initial) && !Object.keys(initial).length
      : Object.is(initial, want);
  const state = {
    seeds: [] as Array<{ after: unknown[]; value: unknown; used?: true }>,
    initials: [] as unknown[],
    /** What useState starts with: `initial`, or the seed whose run of initial values precedes this call. */
    seeded(initial: unknown): unknown {
      const before = state.initials;
      state.initials = [...before, initial];
      for (const seed of state.seeds) {
        if (seed.used || before.length < seed.after.length || initial !== undefined) continue;
        const run = before.slice(before.length - seed.after.length);
        if (!seed.after.every((want, i) => matches(run[i], want))) continue;
        seed.used = true;
        return seed.value;
      }
      return initial;
    },
    reset() {
      state.seeds = [];
      state.initials = [];
    },
  };
  return state;
});

vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  return { ...react, useState: (initial?: unknown) => react.useState(seam.seeded(initial)) };
});
// Nothing a review shows is asked of the worker while it renders: any request stays unanswered.
vi.mock("../src/ui/background", async (original) => {
  const pending = { then: () => pending, catch: () => pending, finally: () => pending };
  return { ...(await original<typeof import("../src/ui/background")>()), call: () => pending };
});

const { t } = await import("../src/i18n");
const { DEFAULT_PREFERENCES } = await import("../src/shared/preferences");
const { NetworkContext } = await import("../src/ui/network");
const { PreferencesContext } = await import("../src/ui/preferences");
const { AccountsContext } = await import("../src/ui/accounts");
const { CardanoSend } = await import("../src/ui/screens/CardanoSend");
const { Withdraw } = await import("../src/ui/screens/Withdraw");
const { adaText } = await import("../src/ui/format");
const { preprodAddress, bech32Bytes } = await import("./fixtures/bech32");
const { loadTestWasm, testBalances, vectors } = await import("./fakes");

const PASSWORD = "correct horse battery";
const v = vectors("cardano_account.json").find((x) => x.account === 0 && x.phrase.split(" ").length === 12)!;
const TX = "ab".repeat(32);
/** Any 28 bytes: a stake key that isn't any account's of this phrase. */
const STRANGERS_STAKE = "cd".repeat(28);
/** 20,000 ₳, as the finding's user sends it. */
const SENT = "20000000000";
const noop = () => undefined;
const none = { lovelace: "0", tokens: [], utxos: 0 };
const cardano = {
  lovelace: "20100000000",
  tokens: [],
  utxos: 3,
  addressesUsed: 1,
  locked: none,
  staking: { registered: true, pool: null, drep: null, rewards: "0", deposit: "2000000" },
};
const seedelf = { lovelace: "20100000000", tokens: [], utxos: 23, seedelfs: [], locked: none };

/** What a person reads of markup. */
const words = (markup: string) =>
  markup
    .replace(/<[^>]+>/g, " ")
    .replaceAll("&#x27;", "'")
    .replaceAll("&amp;", "&")
    .replaceAll("&quot;", '"')
    .replace(/\s+/g, " ")
    .trim();
const has = (markup: string, testId: string) => markup.includes(`data-testid="${testId}"`);
/** A review's row value by its label, of the rows `testId`. */
function row(markup: string, testId: string, label: string): string | undefined {
  const at = markup.indexOf(`data-testid="${testId}"`);
  if (at < 0) return undefined;
  const list = markup.slice(at, markup.indexOf("</dl>", at));
  return [...list.matchAll(/<dt>(.*?)<\/dt><dd[^>]*>(.*?)<\/dd>/g)].map((m) => [words(m[1]!), words(m[2]!)]).find(([l]) => l === words(label))?.[1];
}

/** `element` on preprod, in a wallet of one account, account 0 on screen. */
function render(element: ReactElement): string {
  const accounts = { accounts: [{ index: 0 }], active: 0, loaded: true, name: "Account 1", several: false, reload: async () => undefined };
  return renderToStaticMarkup(
    createElement(
      NetworkContext.Provider,
      { value: "preprod" },
      createElement(
        PreferencesContext.Provider,
        { value: { prefs: DEFAULT_PREFERENCES, loaded: true, set: async () => undefined } },
        createElement(AccountsContext.Provider, { value: accounts }, element),
      ),
    ),
  );
}

/** Send's review of one payment of 20,000 ₳ to `destination`, as SendService.pay puts the worker's answer in it. */
function sendReview(destination: object): string {
  seam.reset();
  // Its state starts after the form's reads', its Max's, its note's and the note's cut's.
  seed([{}, false, "", false], {
    network: "preprod",
    txHash: TX,
    max: false,
    fee: "200000",
    changeLovelace: "99800000",
    changeTokens: 0,
    inputs: 2,
    payments: [{ ...destination, lovelace: SENT, minimum: null, tokens: [] }],
  });
  return render(createElement(CardanoSend, { cardano, total: cardano.lovelace, onCancel: noop, onSent: noop }));
}

/** Make public's review of one payment of 20,000 ₳ to `destination`, as WithdrawService.build's summaryOf has it. */
function makePublicReview(destination: object): string {
  seam.reset();
  seed([{}, false], {
    network: "preprod",
    txHash: TX,
    max: false,
    fee: { size: "500000", compute: "50000", scriptReference: "0", total: "550000" },
    changeLovelace: "99450000",
    changeTokens: 0,
    changeOutputs: 1,
    changeMinimum: "0",
    inputs: 3,
    left: 0,
    payments: [{ ...destination, lovelace: SENT, minimum: null, tokens: [] }],
  });
  return render(createElement(Withdraw, { seedelf, onCancel: noop, onSent: noop }));
}

function seed(after: unknown[], value: unknown) {
  seam.seeds.push({ after, value });
}

/** What a person reads of a review, the address it pays written as one placeholder. */
const read = (markup: string, address: string) => words(markup).replaceAll(address, "‹the address›");

beforeEach(() => seam.reset());

describe("r51 x1a#1: Send and Make public to the account's payment key under a stranger's stake key", () => {
  it("say what the stake part means, as the sign window does, not only what they say of the Receive address", async () => {
    const tb = testBalances();
    await tb.wallet.create(v.phrase, PASSWORD);
    const wasm = loadTestWasm();
    const account = wasm.CardanoAccount.fromPhrase(v.phrase, 0);
    const key = account.paymentKeyHash(0, 0);
    const stake = Buffer.from(bech32Bytes(account.stakeAddress(wasm.Network.Preprod)).slice(1)).toString("hex");
    const { receiveAddress } = await tb.wallet.account("preprod");
    // The Receive address is base(0/0, the account's stake key); the stranger's is base(0/0, their own).
    expect(preprodAddress(key, stake)).toBe(receiveAddress);
    const planted = preprodAddress(key, STRANGERS_STAKE);
    expect(planted).not.toBe(receiveAddress);

    // What the worker has to tell them apart: the payment key is the account's in both, the stake key in one only.
    expect(account.isOwnAddress(planted, [])).toBe(true);
    expect(account.carriesStakeKey(receiveAddress)).toBe(true);
    expect(account.carriesStakeKey(planted)).toBe(false);
    account.free();
    // How the wallet says the same shape in a site's transaction.
    expect(t("dappUi.warn.ownKey")).toContain("a stake part that isn't yours");

    // The worker's answer, as both forms ask it and both builds keep it: the account's own, account 0, for both
    // (§2.17, which stays: the payment key links the money to the account, and the balance reads it).
    const toReceive = await tb.withdraw.resolve("preprod", receiveAddress);
    const toPlanted = await tb.withdraw.resolve("preprod", planted);
    expect(toReceive).toMatchObject({ address: receiveAddress, own: true, ownAccount: 0 });
    expect(toPlanted).toMatchObject({ address: planted, own: true, ownAccount: 0 });
    expect(tb.koios.calls).toHaveLength(0);

    // Send's review, today, for both: "This is your own public account: it comes back, less the fee.", and the
    // 20,000 ₳ not counted as leaving: the total is the fee alone. That much is true of the balance.
    const sendToReceive = sendReview(toReceive);
    const sendToPlanted = sendReview(toPlanted);
    for (const page of [sendToReceive, sendToPlanted]) {
      expect(has(page, "send-own")).toBe(true);
      expect(words(page)).toContain(t("send.warn.ownAccount"));
      expect(row(page, "send-review", t("review.total.public"))).toBe(words(adaText("200000")));
    }
    // Make public's review, today, for both: "This is your own public account: anyone can link it ...".
    const publicToReceive = makePublicReview(toReceive);
    const publicToPlanted = makePublicReview(toPlanted);
    for (const page of [publicToReceive, publicToPlanted]) expect(has(page, "withdraw-own")).toBe(true);

    // The finding (soft, so each is reported). The worker's answer for the stranger's stake part says something its
    // answer for the Receive address doesn't ...
    const { address: _r, ...receiveVerdict } = toReceive;
    const { address: _p, ...plantedVerdict } = toPlanted;
    expect.soft(plantedVerdict, "the worker tells base(0/0, a stranger's stake key) from the Receive address").not.toEqual(receiveVerdict);
    // ... and each review says it: not word for word what it says of the Receive address, and naming the stake.
    expect.soft(read(sendToPlanted, planted), "Send's review tells it from the Receive address").not.toBe(read(sendToReceive, receiveAddress));
    expect.soft(read(publicToPlanted, planted), "Make public's review tells it from the Receive address").not.toBe(
      read(publicToReceive, receiveAddress),
    );
    expect.soft(read(sendToReceive, receiveAddress), "the control: Send's review to the Receive address names no stake").not.toMatch(/stak/i);
    expect.soft(read(sendToPlanted, planted), "Send's review names the stake part that isn't the user's").toMatch(/stak/i);
  });
});

