// Chunk 51, x2#2 (the trace verifier's test). Every Seedelf's register is
// public: its datum is on chain. A stranger re-randomizes one of the user's,
// (g^d, u^d), and pays about 1.34 ₳ (the least that output holds) to the
// enterprise KEY address whose key hash is the wallet contract's script hash,
// with that register as its inline datum. No key has that hash, so nobody can
// ever spend it: the stranger's 1.34 ₳ is burnt.
//
// Koios's credential_utxos takes bare 28-byte hashes, key or script alike
// (koios.ts credentialUtxos), so asked for the contract's it lists this UTxO
// too, and the contract scan (contract-scan.ts:148) reads it. ownedUtxos
// (balances.ts:489) judges a row by its register alone and keeps it, and so
// does WebAssembly's check_spendable (lib.rs:2316). So the private balance
// counts 1.34 ₳ that can never move, and a Seedelf spend that takes it can't
// be built: the builder gives every input a Spend redeemer, and the wallet's
// evaluator (uplc's phase one, run by eval.rs) refuses one on a key-locked
// input. Max takes every UTxO of a balance of 20 or fewer in one part, so Max
// is refused outright, in the evaluator's words.
//
// What's right (the finding's fix): a contract row counts only when its
// payment part is the contract's SCRIPT hash. Then the private balance is
// what it was before the stranger's output landed, and Max pays it as it did.
// Driven through the worker over the fake Koios with the real WebAssembly, as
// transfer.test.ts's "pays the most there is with Max" is.

import { describe, expect, it } from "vitest";

import { CONTRACT_V1 } from "../src/background/balances";
import { registerOf } from "../src/background/chain";
import type { KoiosUtxo } from "../src/background/koios";
import { bech32Bytes, preprodAddress } from "./fixtures/bech32";
import { loadTestWasm, ownedUtxos, testBalances, transferPreprod, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
/** "This is a test.", a live preprod Seedelf the phrase doesn't own. */
const THEIRS = transferPreprod.to;
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");

/**
 * The stranger's output, as Koios's credential_utxos lists it for the contract's hash: 1.34 ₳ at the enterprise KEY
 * address with that hash, under a fresh re-randomization of the user's register (read off the user's own UTxO).
 */
function planted(): KoiosUtxo {
  const wasm = loadTestWasm();
  const found = registerOf(ownedUtxos[0]!)!;
  const base = new wasm.Register(found.generator, found.publicValue);
  const fresh = wasm.rerandomize(base);
  const datum = `d8799f5830${fresh.generator}5830${fresh.publicValue}ff`;
  base.free();
  fresh.free();
  return {
    ...ownedUtxos[0]!,
    tx_hash: "b2".repeat(32),
    tx_index: 0,
    address: preprodAddress(CONTRACT_V1.walletContractHash),
    value: "1340000",
    // The 28 bytes the endpoint matched, as Koios fills it whatever the credential's kind.
    payment_cred: CONTRACT_V1.walletContractHash,
    block_height: 9_000_000,
    inline_datum: { bytes: datum, value: null },
    asset_list: [],
  };
}

describe("x2#2: a UTxO at a key address with the contract's hash", () => {
  it("isn't the wallet's: the private balance doesn't count it, and Max still pays what the wallet can spend", async () => {
    const v = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
    const t = testBalances();
    await t.wallet.create(v.phrase, PASSWORD);
    t.koios.evaluation = transferPreprod.evaluation;

    const row = planted();
    // The contract's preprod address is header 0x70 (enterprise, SCRIPT payment part); the stranger's is the same 28
    // bytes under header 0x60 (enterprise, KEY payment part), which no key spends.
    expect(hex(bech32Bytes(ownedUtxos[0]!.address))).toBe(`70${CONTRACT_V1.walletContractHash}`);
    expect(hex(bech32Bytes(row.address))).toBe(`60${CONTRACT_V1.walletContractHash}`);
    // Its register is the user's, re-randomized: what the wallet's ownership check accepts.
    const wasm = loadTestWasm();
    const reg = registerOf(row)!;
    const asRegister = new wasm.Register(reg.generator, reg.publicValue);
    let owned = false;
    await t.wallet.withKeys((keys) => void (owned = keys.seedelf.isOwned(asRegister)));
    asRegister.free();
    expect(owned).toBe(true);

    // Before it lands: 25 ₳, and 3 ₳ holding tUSDM, and Max spends both (as transfer.test.ts has it).
    const before = await t.balances.get("preprod");
    expect(before.seedelf).toMatchObject({ lovelace: "28000000", utxos: 2 });
    expect(await t.transfer.build("preprod", [{ to: THEIRS, lovelace: null, tokens: [] }])).toMatchObject({
      max: true,
      inputs: 2,
      left: 0,
    });

    // The stranger's output lands, and Koios lists it beside the contract's own.
    t.koios.added.push(row);

    const after = await t.balances.get("preprod", true);
    expect.soft(after.seedelf, "the private balance, with the stranger's unspendable 1.34 ₳ beside it").toMatchObject({
      lovelace: "28000000",
      utxos: 2,
    });

    const max = await t.transfer
      .build("preprod", [{ to: THEIRS, lovelace: null, tokens: [] }])
      .catch((e: unknown) => (e instanceof Error ? e.message : String(e)));
    expect(max, "Max, with the stranger's output beside the wallet's two").toMatchObject({ max: true, inputs: 2, left: 0 });
  });
});

//! Chunk 51, finding x3#1: the connector window reads a Seedelf payment's
//! register with cip30's `register_datum`, which takes constructor 0 only as
//! tag 121. Constructor 0's general form, `102([0, fields])`, is the same
//! Plutus data: the node decodes it as `Constr 0 [g, u]`, the deployed
//! wallet.ak reads that Data, and the wallet's own scan (seedelf-koios
//! `register_of_datum`, chain.ts `registerOf`) reads it as the register. The
//! window labels such an output "none" ("…without a register: whatever goes
//! there, anyone can take."), and Transaction details show no register.
//! This asserts the right behaviour, so it fails while the bug is there.

use pallas_addresses::Address;
use pallas_codec::utils::{Bytes, CborWrap, Nullable, Set};
use pallas_crypto::hash::Hash;
use pallas_primitives::{Fragment, PlutusData, TransactionInput, conway};
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_wasm::cip30::{self, KeyPath, KoiosRow, TxRequest};
use seedelf_wasm::decode::decode_tx;

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TX_A: &str = "1111111111111111111111111111111111111111111111111111111111111111";
/// A register datum: constructor 0 (tag 121, indefinite fields) with the G1
/// generator and a test vector's public value, as cip30_test.rs has it.
const REGISTER_DATUM: &str = "d8799f583097f1d3a73197d7942695638c4fa9ac0fc3688c4f9774b905a14e3a3f171bac586c55e83ff97a1aeffb3af00adb22c6bb583082dcf46570656ca0d6fb143b8e7c2816b20cb1a6434ca4c8c95c624443c22c9e1d40ad0df5de088b19a4b44b685b8475ff";

fn account() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, 0).unwrap()
}

fn keys() -> Vec<KeyPath> {
    (0..3)
        .flat_map(|index| [KeyPath { role: 0, index }, KeyPath { role: 1, index }])
        .collect()
}

fn ours(role: Role, index: u32) -> Address {
    account().base_address(true, role, index).unwrap()
}

fn row(tx: &str, index: u64, address: &Address, lovelace: u64) -> KoiosRow {
    serde_json::from_value(serde_json::json!({
        "tx_hash": tx,
        "tx_index": index,
        "address": address.to_bech32().unwrap(),
        "value": lovelace.to_string(),
        "asset_list": [],
    }))
    .unwrap()
}

fn input(tx: &str, index: u64) -> TransactionInput {
    TransactionInput {
        transaction_id: Hash::new(hex::decode(tx).unwrap().try_into().unwrap()),
        index,
    }
}

fn out(address: &Address, lovelace: u64, datum: &str) -> conway::TransactionOutput {
    conway::PseudoTransactionOutput::PostAlonzo(conway::PostAlonzoTransactionOutput {
        address: Bytes::from(address.to_vec()),
        value: conway::Value::Coin(lovelace),
        datum_option: Some(conway::PseudoDatumOption::Data(CborWrap(
            PlutusData::decode_fragment(&hex::decode(datum).unwrap()).unwrap(),
        ))),
        script_ref: None,
    })
}

fn plain(address: &Address, lovelace: u64) -> conway::TransactionOutput {
    conway::PseudoTransactionOutput::PostAlonzo(conway::PostAlonzoTransactionOutput {
        address: Bytes::from(address.to_vec()),
        value: conway::Value::Coin(lovelace),
        datum_option: None,
        script_ref: None,
    })
}

fn tx_hex(inputs: Vec<TransactionInput>, outputs: Vec<conway::TransactionOutput>) -> String {
    let body = conway::TransactionBody {
        inputs: Set::from(inputs),
        outputs,
        fee: 200_000,
        ttl: Some(99_999_999),
        certificates: None,
        withdrawals: None,
        auxiliary_data_hash: None,
        validity_interval_start: None,
        mint: None,
        script_data_hash: None,
        collateral: None,
        required_signers: None,
        network_id: None,
        collateral_return: None,
        total_collateral: None,
        reference_inputs: None,
        voting_procedures: None,
        proposal_procedures: None,
        treasury_value: None,
        donation: None,
    };
    let tx = conway::Tx {
        transaction_body: body,
        transaction_witness_set: conway::WitnessSet {
            vkeywitness: None,
            native_script: None,
            bootstrap_witness: None,
            plutus_v1_script: None,
            plutus_data: None,
            redeemer: None,
            plutus_v2_script: None,
            plutus_v3_script: None,
        },
        success: true,
        auxiliary_data: Nullable::Null,
    };
    hex::encode(tx.encode_fragment().unwrap())
}

#[test]
fn a_seedelf_payment_in_constructor_0s_general_form_reads_as_under_a_register() {
    // The register's two fields as written: 5830 <g> 5830 <u>.
    let fields = &REGISTER_DATUM[6..REGISTER_DATUM.len() - 2];
    // 102([0, [_ g, u]]): the general form, with the fields indefinite.
    let general_indef = format!("d86682009f{fields}ff");
    // 102([0, [g, u]]): the general form, with the fields definite.
    let general_def = format!("d866820082{fields}");

    // The same Plutus data as the canonical spelling: Pallas compares a
    // constructor by its index and fields, as the ledger reads it.
    let canonical = PlutusData::decode_fragment(&hex::decode(REGISTER_DATUM).unwrap()).unwrap();
    for spelling in [&general_indef, &general_def] {
        let data = PlutusData::decode_fragment(&hex::decode(spelling).unwrap()).unwrap();
        assert_eq!(data, canonical, "{spelling} is Constr 0 [g, u]");
        // Pallas writes it back as written, tag 102 and all: what cip30's
        // output_parts hands register_datum.
        assert_eq!(hex::encode(data.encode_fragment().unwrap()), *spelling);
    }

    // The wallet's own reader, which every Rust spend path and check_spendable
    // use, reads both spellings as the very register the canonical one holds.
    // Holds today.
    let register = seedelf_koios::koios::register_of_datum(&hex::decode(REGISTER_DATUM).unwrap())
        .expect("the canonical register reads");
    assert!(seedelf_core::build::is_payable(&register));
    for spelling in [&general_indef, &general_def] {
        assert_eq!(
            seedelf_koios::koios::register_of_datum(&hex::decode(spelling).unwrap()),
            Some(register.clone()),
            "the wallet's scan reads {spelling} as the register"
        );
    }

    // A site's transaction: the account's 10 ₳ pays 2 ₳ into Seedelf Wallet's
    // contract under each spelling of the same payable register, and its change.
    let contract = seedelf_core::address::wallet_contract(
        true,
        seedelf_core::constants::get_config(1, true)
            .unwrap()
            .contract
            .wallet_contract_hash,
    );
    let rows = vec![row(TX_A, 0, &ours(Role::Receive, 0), 10_000_000)];
    let tx = tx_hex(
        vec![input(TX_A, 0)],
        vec![
            out(&contract, 2_000_000, REGISTER_DATUM),
            out(&contract, 2_000_000, &general_indef),
            out(&contract, 2_000_000, &general_def),
            plain(&ours(Role::Change, 0), 3_800_000),
        ],
    );
    let request = TxRequest {
        network: "preprod".into(),
        tx_cbor: tx.clone(),
        keys: keys(),
        inputs: rows,
        partial_sign: false,
        stake_index: 0,
        stake_deposit: None,
        governance: false,
    };
    let summary = cip30::inspect_tx(&account(), &request).unwrap();
    assert_eq!(summary.paid.len(), 3, "the change is the account's own");
    // The canonical spelling reads as under a register. Holds today.
    assert_eq!(summary.paid[0].seedelf.as_deref(), Some("register"));

    let detail = decode_tx("preprod", &tx).unwrap();
    assert!(detail.outputs[..3].iter().all(|o| o.address.seedelf));
    let shown = |i: usize| {
        detail.outputs[i]
            .register
            .as_ref()
            .map(|r| (r.generator.clone(), r.public_value.clone(), r.payable))
    };
    let expected = Some((register.generator.clone(), register.public_value.clone(), true));
    // Transaction details shows the canonical one under its register. Holds today.
    assert_eq!(shown(0), expected);

    // The same register in the general form must read the same: "register"
    // shows "It pays a Seedelf…", "none" warns "…without a register: whatever
    // goes there, anyone can take." and, with nothing else tied, the privacy
    // line adds "Your private balance isn't in it."
    let mut wrong = Vec::new();
    for (i, spelling) in [(1, "102([0, [_ g, u]])"), (2, "102([0, [g, u]])")] {
        if summary.paid[i].seedelf.as_deref() != Some("register") {
            wrong.push(format!(
                "sign window: output {i}, {spelling}, is labelled {:?}, not \"register\"",
                summary.paid[i].seedelf
            ));
        }
        if shown(i) != expected {
            wrong.push(format!(
                "Transaction details: output {i}, {spelling}, shows register {:?}",
                shown(i)
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

// Chunk 51, x4#1 (the trace verifier's test). A due box's withdraw reads Lovejoin's quiet rule (QUIET_AFTER_SEND_MS)
// once, before its Koios reads and giveme.my's witness (lovejoin.ts withdrawDueNow), and never again before its
// submit (withdrawOne). A Send that goes while giveme.my answers is followed seconds later by the withdraw: the very
// pairing the rule is for ("a withdraw minutes after a payment says both are one owner's"; privacy.md *Timing*:
// "nor within 5 minutes of the wallet's own send"). The right behaviour, asserted here: the withdraw isn't sent in
// that run, nothing is kept as on its way, its box keeps its due time, and it goes once the quiet after the Send is
// over. Fails today: the withdraw is submitted three seconds after the Send.
//
// The real WebAssembly, v2's 5 ₳ pool, a real Send from the public account, and fakes of Koios and giveme.my, set up
// as lovejoin-withdraw-submit.test.ts sets up its withdraws.
import { describe, expect, it, vi } from "vitest";

import { Collateral } from "../src/background/collateral";
import { LovejoinService, QUIET_AFTER_SEND_MS } from "../src/background/lovejoin";
import { lastSpentAt } from "../src/background/spent";
import { SESSION_UNLOCKED_AT } from "../src/background/wallet";
import { txIdOf } from "./fixtures/cbor";
import { busyFor, loadTestWasm, testBalances, vectors } from "./fakes";
import { ADA, ADA_POOL, ADA_ROWS, adaBox, madeByAdaMix, ownDatum } from "./v2-pools";

const PASSWORD = "correct horse battery";
const HOUR = 3_600_000;
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
/** The 15-word phrase's receive address: someone else's. */
const THEIRS = account(15).preprod.receive_0 as string;
/** Each withdraw is built and measured in WebAssembly, and this test builds two, and a payment. */
const SLOW = { timeout: 120_000 };

type T = ReturnType<typeof testBalances>;

/** The Lovejoin record, with the 5 ₳ pool's due times as `due`. */
const kept = async (t: T) => {
  const s = (await t.store.get<{ pools?: Record<string, { due: number[] }>; withdrawing?: object }>("lovejoin.preprod"))!;
  return { ...s, due: s.pools?.[ADA]?.due ?? [] };
};

/**
 * As lovejoin-withdraw-submit.test.ts `due`: the 12-word phrase's wallet, unlocked an hour ago with its unlock's draws
 * made, one box of its own in the 5 ₳ pool, due an hour ago, and giveme.my's witness stood in for.
 */
async function due() {
  const t = testBalances({ pools: [ADA_POOL] });
  await t.wallet.create(account(12).phrase, PASSWORD);
  madeByAdaMix(t.koios, "e1".repeat(32));
  t.koios.addedToAccounts.push(...ADA_ROWS, adaBox("e1", await ownDatum(t.wallet), t.clock.now));
  const unlocked = t.clock.now - HOUR;
  await t.wallet.withKeys(() => t.session.set(SESSION_UNLOCKED_AT, unlocked));
  await t.store.set("lovejoin.preprod", { due: [], pools: { [ADA]: { due: [t.clock.now - HOUR] } }, unlock: unlocked });
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const lovejoin = new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL],
  });
  return { t, lovejoin };
}

describe("r51 x4#1: a withdraw built while the user's Send goes", SLOW, () => {
  it("isn't sent seconds after the Send: it keeps its due time, and goes once the quiet after the Send is over", async () => {
    const { t, lovejoin } = await due();
    // The user reviews a payment from the public account. Nothing has been sent for an hour.
    const review = await t.send.build("preprod", [{ to: THEIRS, lovelace: "3000000", tokens: [] }]);
    expect(await t.wallet.sends()).toEqual({ sent: 0, forgotten: 0 });
    const before = (await kept(t)).due;
    const submits = t.koios.submitted.length;

    // The alarm's run begins (runs.ts `since`), passes the quiet check, reads the pool's reward account, builds the
    // withdraw and asks giveme.my to witness it. Three seconds in, while giveme.my answers, the user presses Send.
    const since = t.clock.now;
    const witness = t.collateral.fetch;
    let paid: number | undefined;
    t.collateral.fetch = async (url, init) => {
      t.clock.now += 3_000;
      paid = t.clock.now;
      // writeAhead stamps a Send's inputs on the device's clock (pending.ts:608), which in the worker is the services'
      // own (sw.ts `now: Date.now`). Here the services run on the test's clock, so the device's is set to it.
      const wall = vi.spyOn(Date, "now").mockReturnValue(paid);
      try {
        await t.send.submit("preprod", review.txHash);
      } finally {
        wall.mockRestore();
      }
      return witness(url, init);
    };
    const went = await lovejoin.withdrawDue("preprod", false, since);
    t.collateral.fetch = witness;

    // giveme.my was asked: the run had passed the quiet check. And the Send went meanwhile, the wallet's last send.
    expect(t.collateral.asked).toHaveLength(1);
    expect(await t.wallet.withKeys(() => lastSpentAt(t.session, t.clock.now))).toBe(paid);
    // Only the Send went out: no withdraw seconds after it.
    expect(t.koios.submitted.slice(submits).map(txIdOf)).toEqual([review.txHash]);
    expect(went).toEqual([]);
    // Nor is it kept as on its way: its box keeps its due time, for a later run.
    expect((await kept(t)).withdrawing).toBeUndefined();
    expect((await kept(t)).due).toHaveLength(before.length);

    // A minute on, still within the quiet after the Send, it doesn't go either.
    await busyFor(t, 60_000);
    await lovejoin.withdrawDue("preprod", false, t.clock.now);
    expect(t.koios.submitted).toHaveLength(submits + 1);

    // Once it's due and the quiet after the Send is over, it goes.
    const [at] = (await kept(t)).due;
    await busyFor(t, Math.max(at!, paid! + QUIET_AFTER_SEND_MS) - t.clock.now);
    const [back] = await lovejoin.withdrawDue("preprod", false, t.clock.now);
    expect(back?.kind).toBe("lovejoin-withdraw");
    expect(t.koios.submitted).toHaveLength(submits + 2);
    expect(t.clock.now - paid!).toBeGreaterThanOrEqual(QUIET_AFTER_SEND_MS);
  });
});

// Chunk 51, x4#2: a swap's step that the unlock's wait let go (sessions.ts waits) before a lock and an unlock,
// both inside its Minswap call, is never sent seconds after that unlock: nothing goes out the moment the wallet
// unlocks (privacy review §3.1, independent review L10-L12). Lovejoin's withdraw refuses the same shape
// (lovejoin.ts lockedWhileBuilding; lovejoin-withdraw-submit.test.ts, "a withdraw built across a lock and an
// unlock"). The harness is unlock-waits.test.ts's "a swap's step at the unlock": the real WebAssembly, and fakes
// of Koios, giveme.my and Minswap.
import { describe, expect, it } from "vitest";

import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { UNLOCK_WAIT_MS } from "../src/background/lovejoin";
import { Minswap } from "../src/background/minswap";
import { SessionService } from "../src/background/sessions";
import { SESSION_UNLOCKED_AT } from "../src/background/wallet";
import { txIdOf } from "./fixtures/cbor";
import { bytes, swapTx } from "./fixtures/swap-tx";
import { busyFor, loadTestWasm, minswapEstimate, sessionSwap, testBalances, vectors, withdrawPreprod } from "./fakes";
import { ADA_ROWS } from "./v2-pools";

const PASSWORD = "correct horse battery";
const PHRASE = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!.phrase;
const SLOW = { timeout: 30_000 };
const SWAP = swapTx();
const SWAP_TX = txIdOf(bytes(SWAP));

type T = ReturnType<typeof testBalances>;

async function unlocked() {
  const t = testBalances();
  await t.wallet.create(PHRASE, PASSWORD);
  // One spend: the funding takes the 25 ₳ UTxO alone.
  const evaluation = withdrawPreprod.amount.evaluation as { result: unknown[] };
  t.koios.evaluation = { ...evaluation, result: evaluation.result.slice(0, 1) };
  return t;
}

/** The session service with giveme.my's witness and the one-time key's signature stood in for. */
function signing(t: T) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  t.minswap.swapCbor = SWAP;
  return new SessionService({
    ...t.deps,
    wasm: {
      ...wasm,
      signScriptSpend: (_key: unknown, request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
    alarm: { start: async () => undefined },
  });
}

/** Session 0's funding sent, and landed: Koios confirms it, and the account holds what the recorded swap spends. */
async function funded(t: T, sessions: SessionService) {
  const out = await sessions.outBuild("preprod", await sessions.quote("preprod", minswapEstimate.ask));
  await sessions.outSubmit("preprod", out.txHash);
  t.koios.confirmations = 1;
  t.koios.addedToAccounts.push({
    ...ADA_ROWS[0]!,
    tx_hash: sessionSwap.utxo.tx_hash,
    tx_index: sessionSwap.utxo.tx_index,
    address: sessionSwap.address,
    value: sessionSwap.utxo.value,
    payment_cred: sessionSwap.keyHash,
    inline_datum: null,
    asset_list: [],
  } as KoiosUtxo);
}

const waitsUntil = async (sessions: SessionService) => (await sessions.list("preprod"))[0]!.auto!.waitsUntil;

describe("r51 x4#2: a swap's step under way across a lock and an unlock", SLOW, () => {
  it("isn't sent seconds after the unlock: it waits the new unlock's fresh draw, then goes", async () => {
    const t = await unlocked();
    const sessions = signing(t);
    await funded(t, sessions);
    // Long into the unlock: the order is due, and no unlock's wait holds it back (waits says go).
    await busyFor(t, UNLOCK_WAIT_MS[1] + 60_000);
    const sent = t.koios.submitted.length;
    const sentSince = () => t.koios.submitted.slice(sent).map((b) => txIdOf(b));
    // The alarm's run reaches the order. While Minswap builds it, the user locks and unlocks again.
    const minswap = t.minswap.fetch;
    let unlockedAt: number | undefined;
    t.minswap.fetch = async (url, init) => {
      if (url.includes("build-tx") && unlockedAt === undefined) {
        await t.wallet.lock();
        t.clock.now += 20_000;
        await t.wallet.unlock(PASSWORD);
        unlockedAt = t.clock.now;
      }
      return minswap(url, init);
    };
    await sessions.runAll("preprod");
    t.minswap.fetch = minswap;
    expect(unlockedAt).toBeDefined();
    expect(await t.wallet.withKeys(() => t.session.get(SESSION_UNLOCKED_AT))).toBe(unlockedAt);
    // Nothing goes out at the moment of the unlock: not the order, nor anything else.
    expect(sentSince()).not.toContain(SWAP_TX);
    expect(sentSince()).toEqual([]);
    // The alarm's next run, a minute on: still nothing, and the step waits a fresh draw from that unlock.
    await busyFor(t, 60_000);
    await sessions.runAll("preprod");
    expect(sentSince()).toEqual([]);
    const until = (await waitsUntil(sessions))!;
    expect(until).toBeGreaterThanOrEqual(unlockedAt! + UNLOCK_WAIT_MS[0]);
    // Once it's past, the order goes: the step is held, never dropped.
    await busyFor(t, until - t.clock.now);
    await sessions.runAll("preprod");
    expect(sentSince()).toEqual([SWAP_TX]);
  });
});
